import { L, card, ci, fl, q } from "./helpers";

// Seerah batch 14 (2026-10-16): al-Raheeq pp. 309–347; al-Umari pp. 406–415, 436–460. Draft, pending scholarly review.

export const s39 = L(39, "mustaliq-ifk", "بنو المصطلق وحديث الإفك", "Banu al-Mustaliq and the Ifk (slander)", [
  card("hook", "hook", "غزوة قصيرة وامتحان كبير", "A short campaign, a great trial",
    "بعد قريظة توالت السرايا التأديبية، ثم خرج النبي ﷺ إلى بني المصطلق. لم تكن الغزوة طويلة عسكريًا، لكن فيها ظهر كيد المنافقين: محاولة إثارة العصبية بين المهاجرين والأنصار، ثم حديث الإفك الذي طُعن فيه بيت النبوة.",
    "After Qurayzah came a run of punitive expeditions, then the Prophet ﷺ marched against Banu al-Mustaliq. Militarily it was short, but in it the hypocrites showed their hand: first an attempt to stir tribal rivalry between the Emigrants and the Ansar, then the Ifk, the slander aimed at the Prophet's household.",
    []),
  card("abu-rafi", "facts", "مقتل أبي رافع", "The killing of Abu Rafiʿ",
    "يقول المباركفوري: «كان سلام بن أبي الحقيق ـ وكنيته أبو رافع ـ من أكابر مجرمي اليهود الذين حزبوا الأحزاب ضد المسلمين»، فاستأذنت الخزرج في قتله، «وأذن رسول الله في قتله ونهي عن قتل النساء والصبيان». فدخل عبد الله بن عتيك حصنه بخيبر فقتله، وانكسرت ساقه، فمسحها النبي ﷺ فبرئت.",
    "Al-Mubarakpuri writes: 'Sallam ibn Abi al-Huqayq, known as Abu Rafiʿ, was one of the chief Jewish criminals who rallied the Confederates against the Muslims'. Al-Khazraj asked permission to kill him, 'and the Messenger of Allah permitted it and forbade killing women and children'. ʿAbdullah ibn ʿAtik got into his fortress at Khaybar and killed him. ʿAbdullah broke his leg, and the Prophet ﷺ wiped it and it healed.",
    [ci("raheeq_p309_s", "grading_unverified", "كان سلام بن أبي الحقيق ـ وكنيته أبو رافع ـ من أكابر مجرمي اليهود الذين حزبوا الأحزاب ضد المسلمين"), ci("raheeq_p309_t", "grading_unverified", "وأذن رسول الله في قتله ونهي عن قتل النساء والصبيان")]),
  card("abu-rafi-versions", "context", "روايتان في التفاصيل", "Two versions of the details",
    "يقول المؤلف بعد سياق القصة: «هذه رواية البخاري، وعند ابن إسحاق أن جميع النفر دخلوا على أبي رافع واشتركوا في قتله»، وأن الذي قتله عند ابن إسحاق عبد الله بن أنيس.",
    "After telling the story the author says: 'this is al-Bukhari's report; Ibn Ishaq has all the party go in to Abu Rafiʿ and take part in killing him', and in Ibn Ishaq's version the one who killed him was ʿAbdullah ibn Unays.",
    [ci("raheeq_p310_s", "grading_unverified", "هذه رواية البخاري، وعند ابن إسحاق أن جميع النفر دخلوا على أبي رافع واشتركوا في قتله")],
    [fl("conflict", "رواية البخاري (ابن عتيك وحده دخل) تخالف رواية ابن إسحاق (دخلوا جميعًا وقتله ابن أنيس). لم نطّلع على نص البخاري مباشرة.", "Al-Bukhari's report (Ibn ʿAtik went in alone) differs from Ibn Ishaq's (they all went in, and Ibn Unays killed him). We have not checked al-Bukhari's text directly.")]),
  card("thumamah", "narrative", "ثمامة بن أثال", "Thumamah ibn Uthal",
    "أُسر ثمامة سيد بني حنيفة ورُبط بسارية المسجد، فكان يقول: «عندي خير يا محمد، إن تقتل تقتل ذا دم، وإن تنعم تنعم على شاكر». فأطلقه النبي ﷺ، فاغتسل وأسلم وقال: «فقد أصبح وجهك أحب الوجوه إلى». ثم قال لقريش: «ولا والله لا يأتيكم من اليمامة حبة حنطة حتى يأذن فيها رسول الله صلى الله عليه وسلم».",
    "Thumamah, chief of Banu Hanifah, was captured and tied to a pillar of the mosque. He kept saying: 'I have good, Muhammad: if you kill, you kill a man whose blood will be avenged; if you show favour, you show it to a grateful man.' The Prophet ﷺ freed him; he bathed, accepted Islam and said: 'your face has become the dearest of faces to me.' Then he told Quraysh: 'By Allah, not one grain of wheat will reach you from al-Yamamah until the Messenger of Allah ﷺ permits it.'",
    [ci("raheeq_p310_t", "grading_unverified", "عندي خير يا محمد، إن تقتل تقتل ذا دم، وإن تنعم تنعم على شاكر"), ci("raheeq_p310_u", "grading_unverified", "فقد أصبح وجهك أحب الوجوه إلى"), ci("raheeq_p311_s", "grading_unverified", "ولا والله لا يأتيكم من اليمامة حبة حنطة حتى يأذن فيها رسول الله صلى الله عليه وسلم")],
    [fl("gap", "لم نتحقق من تخريج القصة؛ الرحيق يسوقها دون عزو في هذه الصفحة.", "We have not verified the story's source; al-Raheeq tells it without a reference on this page.")]),
  card("lihyan", "facts", "غزوة بني لحيان", "The campaign against Banu Lihyan",
    "خرج النبي ﷺ في ربيع الأول أو جمادى الأولى سنة ٦هـ في مائتين يطلب ثأر أصحاب الرجيع، فلما بلغ موضع مصابهم «فترحم عليهم ودعا لهم، وسمعت به بنو لحيان فهربوا في رءوس الجبال».",
    "In Rabiʿ al-Awwal or Jumada al-Ula, 6 AH, the Prophet ﷺ set out with two hundred men to avenge the companions killed at al-Rajiʿ. When he reached the place where they died, 'he asked mercy for them and prayed for them; Banu Lihyan heard of him and fled to the mountain tops.'",
    [ci("raheeq_p311_t", "grading_unverified", "فترحم عليهم ودعا لهم، وسمعت به بنو لحيان فهربوا في رءوس الجبال")],
    [fl("conflict", "الشهر غير محدد في المصدر: ربيع الأول أو جمادى الأولى.", "The month is not fixed in the source: Rabiʿ al-Awwal or Jumada al-Ula.")]),
  card("abul-as", "narrative", "أبو العاص وزينب", "Abu al-ʿAs and Zaynab",
    "في سرية العيص أُخذت عير لقريش قائدها أبو العاص صهر النبي ﷺ، «وأفلت أبو العاص، فأتي زينب فاستجار بها»، فرُدّت أمواله، ثم أسلم وردّ النبي ﷺ عليه زينب. ويقول المؤلف عن الرواية المخالفة: «وأما ما ورد من الحديث من أنه رد عليه بنكاح جديد، أو رد عليه بعد ست سنين فلا يصح معني»، ولا سندًا عنده.",
    "On the al-ʿIs expedition a Quraysh caravan led by Abu al-ʿAs, the Prophet's ﷺ son-in-law, was seized. 'Abu al-ʿAs escaped, came to Zaynab and sought her protection', and his goods were returned. He later accepted Islam and the Prophet ﷺ returned Zaynab to him. On the opposing report the author says: 'as for the hadith that she was returned with a new marriage, or after six years, it is not sound in meaning', nor in chain, in his view.",
    [ci("raheeq_p312_s", "grading_unverified", "وأفلت أبو العاص، فأتي زينب فاستجار بها"), ci("raheeq_p312_t", "grading_unverified", "وأما ما ورد من الحديث من أنه رد عليه بنكاح جديد، أو رد عليه بعد ست سنين فلا يصح معني")],
    [fl("weak", "يضعّف المؤلف رواية «النكاح الجديد» سندًا ومعنى، ويصحح الرد بالنكاح الأول؛ ولم ننقل التخريج.", "The author rejects the 'new marriage' report in both chain and meaning and affirms the return under the first marriage; we have not carried over the takhrij."), fl("conflict", "جعل موسى بن عقبة الحادثة سنة ٧هـ، والمؤلف يرده.", "Musa ibn ʿUqbah put the event in 7 AH; the author rejects that.")]),
  card("khabat", "narrative", "سرية الخبط والعنبر", "The Khabat expedition and the whale",
    "بعث النبي ﷺ أبا عبيدة في ثلاثمائة، فجاعوا حتى أكلوا ورق الشجر (الخبط)، فألقى البحر لهم دابة عظيمة أكلوا منها نصف شهر، فقال ﷺ: «هو رزق أخرجه الله لكم». ويقول المؤلف عن تاريخها: «وإنما قلنا: إن سياق هذه السرية يدل على أنها كانت قبل الحديبية»؛ لأن المسلمين لم يتعرضوا لعير قريش بعد الصلح.",
    "The Prophet ﷺ sent Abu ʿUbaydah with three hundred men. They went so hungry that they ate leaves (khabat), and then the sea threw up a huge creature for them, which they ate for half a month. He ﷺ said: 'It is provision Allah brought out for you.' On its date the author says: 'we said the course of this expedition shows it was before al-Hudaybiyah', because the Muslims did not intercept Quraysh caravans after the treaty.",
    [ci("raheeq_p313_s", "grading_unverified", "هو رزق أخرجه الله لكم"), ci("raheeq_p313_t", "grading_unverified", "وإنما قلنا: إن سياق هذه السرية يدل على أنها كانت قبل الحديبية")],
    [fl("conflict", "تُذكر السرية في رجب سنة ٨هـ، والمؤلف يرى أنها قبل الحديبية.", "The expedition is dated Rajab 8 AH in some sources; the author places it before al-Hudaybiyah.")]),
  card("mustaliq-date", "context", "تاريخ غزوة بني المصطلق", "The date of the Banu al-Mustaliq campaign",
    "يقول المباركفوري: «كانت هذه الغزوة في شعبان سنة خمس عند عامة أهل المغازي، وسنة ست على قول ابن إسحاق.» ويرجّح العمري سنة خمس؛ فقد ذكر قول ابن إسحاق «أما ابن إسحق فذهب إلى أنها في شعبان سنة ست» ثم ردّه بأن سعد بن معاذ شهدها في الصحيحين، «فلا يمكن أن تكون غزوة بني المصطلق إلا قبل الخندق».",
    "Al-Mubarakpuri: 'this campaign was in Shaʿban of year five according to most Maghazi writers, and year six according to Ibn Ishaq.' Al-ʿUmari prefers year five. He cites 'Ibn Ishaq held it was in Shaʿban of year six' and rejects this because, in the two Sahihs, Saʿd ibn Muʿadh took part in it, 'so the Banu al-Mustaliq campaign can only have been before the Trench'.",
    [ci("raheeq_p314_s", "grading_unverified", "كانت هذه الغزوة في شعبان سنة خمس عند عامة أهل المغازي، وسنة ست على قول ابن إسحاق."), ci("umari_p406_ishaq", "grading_unverified", "أما ابن إسحق فذهب إلى أنها في شعبان سنة ست"), ci("umari_p406_before", "grading_unverified", "فلا يمكن أن تكون غزوة بني المصطلق إلا قبل الخندق")],
    [fl("conflict", "السنة مختلف فيها: خمس عند الجمهور، وست عند ابن إسحاق. ويضع الرحيق الغزوة بعد قريظة، والعمري يرى أنها قبل الخندق.", "The year is disputed: five per most, six per Ibn Ishaq. Al-Raheeq places the campaign after Qurayzah; al-ʿUmari holds it came before the Trench.")]),
  card("battle", "facts", "هل كان قتال؟", "Was there fighting?",
    "ذكر أهل المغازي أنهم تراموا بالنبل ثم حمل المسلمون. ونقل المباركفوري عن ابن القيم ردّ ذلك: «فإنه لم يكن بينهم قتال، وإنما أغار عليهم على الماء فسبي ذراريهم وأموالهم». ويقول العمري: «ورواية مسلم صريحة في أن الغارة وقعت دون إنذار»؛ لأن الدعوة كانت قد بلغتهم. وعن تفاصيل الواقدي في عدد القتلى والغنائم: «ولا عبرة بقول الواقدي إذا انفرد».",
    "The Maghazi writers say the two sides exchanged arrows and then the Muslims charged. Al-Mubarakpuri quotes Ibn al-Qayyim rejecting this: 'there was no fighting between them; he raided them at the water and took their families and property captive'. Al-ʿUmari: 'Muslim's report is explicit that the raid came without warning', since the call to Islam had already reached them. On al-Waqidi's details of the dead and the spoils: 'al-Waqidi's word counts for nothing when he is alone in it'.",
    [ci("raheeq_p315_s", "grading_unverified", "فإنه لم يكن بينهم قتال، وإنما أغار عليهم على الماء فسبي ذراريهم وأموالهم"), ci("umari_p407_raid", "grading_unverified", "ورواية مسلم صريحة في أن الغارة وقعت دون إنذار"), ci("umari_p407_waqidi", "grading_unverified", "ولا عبرة بقول الواقدي إذا انفرد")],
    [fl("conflict", "ابن إسحاق يذكر قتالًا عند المريسيع، ورواية الصحيحين لا تذكر مقاومة.", "Ibn Ishaq mentions fighting at al-Muraysiʿ; the report in the two Sahihs mentions no resistance.")]),
  card("juwayriyah", "facts", "جويرية بنت الحارث", "Juwayriyah bint al-Harith",
    "وقعت جويرية بنت سيد القوم في السبي، فكاتبت، فأدّى عنها النبي ﷺ وتزوجها، فأعتق المسلمون من أسلم من أهلها وقالوا: أصهار رسول الله ﷺ. ويقول العمري: «وقد أسلم الحارث بن أبي ضرار وقومه». وقد أشار العمري في الحاشية إلى أن بعض أخبار ذلك إسناده «لكنه من مراسيل أبي قلابة الجرمي».",
    "Juwayriyah, the daughter of the tribe's chief, was among the captives. She made a contract to buy her freedom; the Prophet ﷺ paid it and married her, and the Muslims freed those of her people who had become Muslim, saying: 'They are in-laws of the Messenger of Allah ﷺ.' Al-ʿUmari: 'al-Harith ibn Abi Dirar and his people accepted Islam'. In a footnote he notes that one of the reports on this has a reliable chain 'but it is one of the mursal reports of Abu Qilabah al-Jarmi'.",
    [ci("umari_p413_harith", "grading_unverified", "وقد أسلم الحارث بن أبي ضرار وقومه"), ci("umari_p413_qilabah", "grading_unverified", "لكنه من مراسيل أبي قلابة الجرمي")],
    [fl("weak", "بعض أخبار تخيير جويرية وإسلام أبيها مرسلة (العمري ص ٤١٣).", "Some reports about Juwayriyah being given the choice and her father's Islam are mursal (al-ʿUmari p. 413).")]),
  card("ibn-ubayy", "context", "ابن أبي قبل الغزوة", "Ibn Ubayy before the campaign",
    "كان ابن أبي يقوم كل جمعة يحث على نصرة النبي ﷺ، فلما قام بعد أحد أخذ المسلمون بثيابه وقالوا: «اجلس أي عدو الله، لست لذلك بأهل وقد صنعت ما صنعت». ولما تزوج النبي ﷺ زينب بنت جحش أكثر المنافقون الدعاية، «واختلقوا قصصا وأساطير» حتى نزل القرآن بالرد.",
    "Ibn Ubayy used to stand every Friday urging people to support the Prophet ﷺ. When he stood up after Uhud the Muslims grabbed his clothes and said: 'Sit down, enemy of Allah; you are not fit for this after what you did.' When the Prophet ﷺ married Zaynab bint Jahsh, the hypocrites spread propaganda 'and invented stories and legends' until the Qurʾan answered them.",
    [ci("raheeq_p316_s", "grading_unverified", "اجلس أي عدو الله، لست لذلك بأهل وقد صنعت ما صنعت"), ci("raheeq_p317_s", "grading_unverified", "واختلقوا قصصا وأساطير")],
    [fl("gap", "لم نتحقق من إسناد خبر قيام ابن أبي يوم الجمعة؛ الرحيق يسوقه دون عزو هنا.", "We have not verified the chain of the report about Ibn Ubayy standing on Fridays; al-Raheeq gives it without a reference here.")]),
  card("asabiyyah", "narrative", "«دعوها فإنها منتنة»", "'Leave it, it is rotten'",
    "ازدحم أجير لعمر ورجل من جهينة على الماء، فنادى هذا: يا للأنصار، وذاك: يا للمهاجرين، فقال ﷺ: «أبدعوي الجاهلية وأنا بين أظهركم؟». فقال ابن أبي: ليخرجن الأعز منها الأذل. واستأذن عمر في قتله، فقال ﷺ: «فكيف يا عمر إذا تحدث الناس أن محمدا يقتل أصحابه؟». ويستشهد العمري بزيد بن أرقم: «ولندع الصحابي زيد بن أرقم وهو شاهد عيان».",
    "A hired man of ʿUmar's and a man from Juhaynah crowded each other at the water. One called 'O Ansar!' and the other 'O Emigrants!', and he ﷺ said: 'The call of Jahiliyyah, while I am among you?' Ibn Ubayy said: 'the mightier will drive out the humbler.' ʿUmar asked to kill him, and he ﷺ said: 'How would it be, ʿUmar, if people said Muhammad kills his companions?' Al-ʿUmari tells it through Zayd ibn Arqam: 'let the Companion Zayd ibn Arqam, an eyewitness, tell it'.",
    [ci("raheeq_p318_s", "grading_unverified", "أبدعوي الجاهلية وأنا بين أظهركم؟"), ci("raheeq_p318_t", "grading_unverified", "فكيف يا عمر إذا تحدث الناس أن محمدا يقتل أصحابه؟"), ci("umari_p408_zayd", "grading_unverified", "ولندع الصحابي زيد بن أرقم وهو شاهد عيان")],
    [fl("conflict", "وردت روايات بأن ابن أبي قال ذلك في تبوك، ويقول العمري: «وهو وهم والصحيح أنه لم يشهد غزوة تبوك» (ص ٤٠٩).", "Some reports say Ibn Ubayy said this at Tabuk; al-ʿUmari says 'that is a mistake; the correct view is that he did not take part in Tabuk' (p. 409).")]),
  card("usayd-zayd", "facts", "أسيد وزيد بن أرقم", "Usayd and Zayd ibn Arqam",
    "أمر النبي ﷺ بالرحيل في ساعة غير معتادة ليشغل الناس، فقال أسيد بن حضير عن ابن أبي: «هو والله الذليل وأنت العزيز». وحلف ابن أبي أنه ما قال، فاغتم زيد بن أرقم، حتى نزلت سورة المنافقون، فقال ﷺ لزيد: «إن الله قد صدقك».",
    "The Prophet ﷺ ordered the march at an unusual hour to keep people busy. Usayd ibn Hudayr said of Ibn Ubayy: 'By Allah, he is the humble one and you are the mighty.' Ibn Ubayy swore he had not said it, and Zayd ibn Arqam was grieved, until Surat al-Munafiqun came down and he ﷺ told Zayd: 'Allah has confirmed you.'",
    [ci("raheeq_p318_u", "grading_unverified", "هو والله الذليل وأنت العزيز"), ci("raheeq_p319_s", "grading_unverified", "إن الله قد صدقك"), ci("umari_p409_tabuk", "grading_unverified", "وهو وهم والصحيح أنه لم يشهد غزوة تبوك")]),
  card("son", "narrative", "عبد الله بن عبد الله بن أبي", "ʿAbdullah, son of ʿAbdullah ibn Ubayy",
    "كان ابنه صحابيًا صالحًا، فوقف لأبيه على باب المدينة وقال: «والله لا تجوز من هاهنا حتى يأذن لك رسول الله صلى الله عليه وسلم، فإنه العزيز وأنت الذليل». واستأذن في قتل أبيه، فقال له ﷺ كما يذكر العمري: «ولكن بر أباك وأحسن صحبته».",
    "His son was a righteous Companion. He stood at the gate of Madinah and told his father: 'By Allah, you will not pass here until the Messenger of Allah ﷺ gives you permission, for he is the mighty one and you are the humble.' He asked permission to kill his father, and, as al-ʿUmari reports, he ﷺ told him: 'Rather, be dutiful to your father and keep good company with him.'",
    [ci("raheeq_p319_t", "grading_unverified", "والله لا تجوز من هاهنا حتى يأذن لك رسول الله صلى الله عليه وسلم، فإنه العزيز وأنت الذليل"), ci("umari_p410_birr", "grading_unverified", "ولكن بر أباك وأحسن صحبته")],
    [fl("gap", "لم ننقل حكم العمري على إسناد خبر استئذان الابن؛ يُراجع الحاشية (ص ٤١٠).", "We have not carried over al-ʿUmari's grading of the son's request; check the footnote (p. 410).")]),
  card("ifk-1", "narrative", "حديث الإفك (١): العقد والهودج", "The Ifk (1): the necklace and the litter",
    "يذكر المباركفوري أن عائشة رضي الله عنها «كانت قد خرج بها رسول الله صلى الله عليه وسلم معه في هذه الغزوة بقرعة أصابتها». ففقدت عقدًا فرجعت تلتمسه، فحُمل هودجها وهم يظنونها فيه، فبقيت في المنزل حتى جاء صفوان بن المعطل، فأناخ لها راحلته، «وما كلمها كلمة واحدة، ولم تسمع منه إلا استرجاعه».",
    "ʿAʾishah: 'the Messenger of Allah ﷺ had taken her with him on this campaign by a lot that fell to her'. She lost a necklace and went back to look for it. Her litter was loaded while they thought she was inside, so she was left at the camp until Safwan ibn al-Muʿattal came. He knelt his camel for her, 'and he did not say a single word to her; she heard nothing from him but his saying inna lillah'.",
    [ci("raheeq_p319_u", "grading_unverified", "كانت قد خرج بها رسول الله صلى الله عليه وسلم معه في هذه الغزوة بقرعة أصابتها"), ci("raheeq_p319_v", "grading_unverified", "وما كلمها كلمة واحدة، ولم تسمع منه إلا استرجاعه")],
    [fl("gap", "الرحيق يلخص الحديث الطويل في الصحيحين؛ لم نطّلع على النص الكامل في البخاري ومسلم.", "Al-Raheeq summarises the long hadith in the two Sahihs; we have not read the full text in al-Bukhari and Muslim.")]),
  card("ifk-2", "narrative", "حديث الإفك (٢): الشهر الطويل", "The Ifk (2): the long month",
    "أشاع ابن أبي الإفك، «وقد انقطع الوحي شهراً» كما يقول العمري. واستشار النبي ﷺ أصحابه، «فأشار عليه علي رضي الله عنه أن يفارقها، ويأخذ غيرها، تلويحا لاتصريحا»، وأشار أسامة بإمساكها. ولما علمت عائشة «فبكت ليلتين ويوما، لم تكن تكتحل بنوم». وقال أبو أيوب لما سمع: «سبحانك هذا بهتان عظيم».",
    "Ibn Ubayy spread the slander, and, as al-ʿUmari says, 'the revelation stopped for a month'. The Prophet ﷺ consulted his companions; 'ʿAli advised him to part from her and take another, by hint rather than outright', while Usamah advised keeping her. When ʿAʾishah learned of it, 'she wept two nights and a day, with no sleep in her eyes'. When Abu Ayyub heard it he said: 'Glory be to You, this is a great slander.'",
    [ci("umari_p411_wahy", "grading_unverified", "وقد انقطع الوحي شهراً"), ci("raheeq_p319_w", "grading_unverified", "فأشار عليه علي رضي الله عنه أن يفارقها، ويأخذ غيرها، تلويحا لاتصريحا"), ci("raheeq_p320_s", "grading_unverified", "فبكت ليلتين ويوما، لم تكن تكتحل بنوم"), ci("umari_p412_ayyub", "grading_unverified", "سبحانك هذا بهتان عظيم")],
    [fl("conflict", "الذي أبدى استعداده لقتل القاذف: أسيد بن حضير في الرحيق، وسعد بن معاذ عند العمري؛ وفيه إشكال لأن سعدًا مات بعد قريظة، وهذا من أدلة تقديم الغزوة.", "Who offered to kill the slanderer: Usayd ibn Hudayr in al-Raheeq, Saʿd ibn Muʿadh in al-ʿUmari. This is a known problem because Saʿd died after Qurayzah, and it is one of the arguments for dating the campaign earlier.")]),
  card("ifk-3", "narrative", "حديث الإفك (٣): البراءة", "The Ifk (3): the acquittal",
    "قال لها ﷺ: «فإن كنت بريئة فسيبرئك الله، وإن كنت ألممت بذنب فاستغفري الله وتوبي إليه». فاستشهدت بقول أبي يوسف: فصبر جميل. ونزل الوحي، فكانت أول كلمة: «يا عائشة، أما الله فقد برأك»، فقالت: «والله لا أقوم إليه، ولا أحمد إلا الله.» ونزلت آيات النور. وكان أبو بكر حلف ألا ينفق على مسطح، فنزلت ﴿ولا يأتل أولو الفضل﴾، «فعاد أبو بكر إلى النفقة عليه».",
    "He ﷺ said to her: 'If you are innocent, Allah will declare you innocent; if you have slipped into a sin, ask Allah's forgiveness and repent to Him.' She answered with the words of Yusuf's father: 'patience is fitting'. Revelation came, and his first words were: 'ʿAʾishah, Allah has declared you innocent.' She said: 'By Allah, I will not get up to him, and I praise no one but Allah.' The verses of al-Nur were revealed. Abu Bakr had sworn to stop supporting Mistah; then 'Let not those of grace among you swear…' came down, 'and Abu Bakr went back to supporting him'.",
    [ci("raheeq_p320_t", "grading_unverified", "فإن كنت بريئة فسيبرئك الله، وإن كنت ألممت بذنب فاستغفري الله وتوبي إليه"), ci("raheeq_p320_u", "grading_unverified", "يا عائشة، أما الله فقد برأك"), ci("raheeq_p320_v", "grading_unverified", "والله لا أقوم إليه، ولا أحمد إلا الله."), ci("umari_p411_mistah", "grading_unverified", "فعاد أبو بكر إلى النفقة عليه")]),
  card("hadd", "context", "حد القذف", "The penalty for slander",
    "جُلد مسطح وحسان وحمنة حد القذف، ولم يُحدّ ابن أبي في المشهور؛ لأن الحدود كفارة، أو لمصلحة. ويقول العمري: «وقد وردت أحاديث ضعيفة تفيد إقامة الحد عليه أيضاً».",
    "Mistah, Hassan and Hamnah were flogged with the penalty for slander. In the well-known account Ibn Ubayy was not, because the penalties are an expiation, or for a wider interest. Al-ʿUmari: 'weak hadiths have come saying the penalty was applied to him as well'.",
    [ci("umari_p412_weak", "grading_unverified", "وقد وردت أحاديث ضعيفة تفيد إقامة الحد عليه أيضاً")],
    [fl("weak", "أحاديث جلد ابن أبي ضعيفة عند العمري (ص ٤١٢).", "The reports that Ibn Ubayy was flogged are weak per al-ʿUmari (p. 412).")]),
  card("umar-lesson", "facts", "«أعظم بركة من أمري»", "'More blessed than my counsel'",
    "صار قوم ابن أبي هم الذين يعنفونه، فقال ﷺ لعمر: «أما والله لوقتلته يوم قلت لي: اقتله، لأرعدت له آنف»، فقال عمر: «لأمر رسول الله صلى الله عليه وسلم أعظم بركة من أمري.»",
    "Ibn Ubayy's own people became the ones who rebuked him. He ﷺ said to ʿUmar: 'By Allah, had I killed him the day you told me to, noses would have trembled with anger for him.' ʿUmar said: 'The Messenger of Allah's ﷺ judgment is more blessed than mine.'",
    [ci("raheeq_p321_s", "grading_unverified", "أما والله لوقتلته يوم قلت لي: اقتله، لأرعدت له آنف"), ci("raheeq_p321_t", "grading_unverified", "لأمر رسول الله صلى الله عليه وسلم أعظم بركة من أمري.")],
    [fl("no_chain", "الخبر من ابن إسحاق في الرحيق؛ لم نتحقق من إسناده.", "The report is from Ibn Ishaq in al-Raheeq; its chain is unverified.")]),
  card("lessons", "context", "أحكام وعبر عند العمري", "Rulings and lessons per al-ʿUmari",
    "يذكر العمري: «ومن الأحكام المستنبطة من هذه الغزوة جواز الإغارة على من بلغتهم دعوة الإسلام دون إنذار»، وجواز جعل العتق صداقًا، وإقامة حد القذف. ويرى في الإفك دليلًا على بشرية النبي ﷺ وأن الوحي ليس منه؛ «فإنه لم يتمكن من الكشف عن الغيب أو استحضار الوحي الذي انقطع عنه شهرا».",
    "Al-ʿUmari lists: 'among the rulings drawn from this campaign is that it is permitted to raid, without warning, those whom the call to Islam has reached', that freeing a slave can serve as a bride gift, and that the slander penalty is applied. He sees in the Ifk proof of the Prophet's ﷺ humanity and that revelation did not come from himself: 'he could not uncover the unseen or summon the revelation that had stopped for a month'.",
    [ci("umari_p414_ahkam", "grading_unverified", "ومن الأحكام المستنبطة من هذه الغزوة جواز الإغارة على من بلغتهم دعوة الإسلام دون إنذار"), ci("umari_p415_bashar", "grading_unverified", "فإنه لم يتمكن من الكشف عن الغيب أو استحضار الوحي الذي انقطع عنه شهرا")]),
  card("sariyyas", "facts", "سرايا بعد المريسيع", "Expeditions after al-Muraysiʿ",
    "أرسل النبي ﷺ عبد الرحمن بن عوف إلى دومة الجندل وقال له: «إن أطاعوك فتزوج ابنة ملكهم»، فأسلموا. وبعث عليًا إلى فدك، ثم كانت «سرية أبي بكر الصديق أو زيد بن حارثة إلى وادي القري». وفي العرنيين الذين قتلوا الراعي يقول المؤلف: «وحديثهم في الصحيح عن أنس.» ويقول عن سرية عمرو بن أمية: «فلا أدري هل اختلط السفران على أهل السير».",
    "The Prophet ﷺ sent ʿAbd al-Rahman ibn ʿAwf to Dumat al-Jandal, telling him: 'If they obey you, marry their king's daughter', and they accepted Islam. He sent ʿAli to Fadak, then came 'the expedition of Abu Bakr al-Siddiq, or Zayd ibn Harithah, to Wadi al-Qura'. Of the ʿUranis who killed the herdsman the author says: 'their story is in the Sahih from Anas.' Of ʿAmr ibn Umayyah's mission he says: 'I do not know whether the Seerah writers mixed up the two journeys'.",
    [ci("raheeq_p322_s", "grading_unverified", "إن أطاعوك فتزوج ابنة ملكهم"), ci("raheeq_p322_t", "grading_unverified", "سرية أبي بكر الصديق أو زيد بن حارثة إلى وادي القري"), ci("raheeq_p323_s", "grading_unverified", "وحديثهم في الصحيح عن أنس."), ci("raheeq_p323_t", "grading_unverified", "فلا أدري هل اختلط السفران على أهل السير")],
    [fl("conflict", "أمير سرية وادي القرى: أبو بكر أو زيد بن حارثة.", "The leader of the Wadi al-Qura expedition: Abu Bakr or Zayd ibn Harithah."), fl("conflict", "خبر سرية عمرو بن أمية إلى مكة مضطرب عند المؤلف.", "The author finds the report of ʿAmr ibn Umayyah's mission to Makkah confused.")]),
  card("reflection", "reflection", "حين يكون الطعن في البيت", "When the attack comes at home",
    "تأمل (ليس رواية): لم يقدر المنافقون على النبي ﷺ بالسيف، فحاولوا بالكلام: العصبية، ثم الطعن في الأعراض. وكانت المواجهة بالصبر والتثبت، وحفظ وحدة الصف، حتى جاء الحق من الله. ويرى المباركفوري أن ما بعد الأحزاب لم يكن إلا تمهيدًا للحديبية التي لم تكن «الهدنة إلا الاعتراف بقوة الإسلام».",
    "Reflection (not a source claim): the hypocrites could not defeat the Prophet ﷺ with the sword, so they tried with words: first tribal rivalry, then attacks on honour. He met them with patience and verification, and kept the ranks united until the truth came from Allah. Al-Mubarakpuri sees the period after the Trench as leading up to al-Hudaybiyah, where 'the truce was nothing but a recognition of Islam's strength'.",
    [ci("raheeq_p323_u", "grading_unverified", "الهدنة إلا الاعتراف بقوة الإسلام")]),
  card("summary", "summary", "خلاصة الدرس", "Lesson summary",
    "بعد قريظة: قُتل أبو رافع، وأسلم ثمامة، وطُلب ثأر الرجيع. وفي بني المصطلق (شعبان ٥هـ عند الأكثر) أغار المسلمون على الماء، وتزوج النبي ﷺ جويرية فأُعتق قومها. وحاول ابن أبي إثارة العصبية فقال: ليخرجن الأعز منها الأذل، ثم أشاع الإفك، فانقطع الوحي شهرًا، ثم نزلت براءة عائشة في سورة النور، وأقيم حد القذف.",
    "After Qurayzah: Abu Rafiʿ was killed, Thumamah became Muslim, and al-Rajiʿ was avenged. At Banu al-Mustaliq (Shaʿban 5 AH per most) the Muslims raided them at the water, and the Prophet ﷺ married Juwayriyah, so her people were freed. Ibn Ubayy tried to stir tribal rivalry, saying 'the mightier will drive out the humbler', then spread the Ifk. Revelation stopped for a month, then ʿAʾishah's innocence was revealed in Surat al-Nur and the slander penalty was applied.",
    []),
], [
  q("q1", "thumamah", "ماذا فعل ثمامة بعد إسلامه؟", "What did Thumamah do after accepting Islam?", [["منع الحنطة عن قريش حتى يأذن النبي ﷺ", "He stopped wheat reaching Quraysh until the Prophet ﷺ permitted it"], ["رجع إلى دينه", "He went back to his old religion"], ["هاجر إلى الحبشة", "He migrated to Abyssinia"]], 0, "وكانت اليمامة ريف مكة.", "Al-Yamamah was Makkah's breadbasket."),
  q("q2", "mustaliq-date", "لماذا يرى العمري أن غزوة بني المصطلق قبل الخندق؟", "Why does al-ʿUmari place Banu al-Mustaliq before the Trench?", [["لأن سعد بن معاذ شهدها وقد مات بعد قريظة", "Saʿd ibn Muʿadh took part in it and he died after Qurayzah"], ["لأن ابن إسحاق قال ذلك", "Because Ibn Ishaq said so"], ["لأن الواقدي انفرد به", "Because al-Waqidi alone says so"]], 0, "وابن إسحاق يجعلها سنة ست.", "Ibn Ishaq puts it in year six."),
  q("q3", "battle", "ماذا قال ابن القيم عن القتال في المريسيع؟", "What did Ibn al-Qayyim say about fighting at al-Muraysiʿ?", [["لم يكن بينهم قتال، وإنما أغار عليهم", "There was no fighting; he raided them"], ["كانت معركة طويلة", "It was a long battle"], ["انهزم المسلمون", "The Muslims were defeated"]], 0, "كما في الصحيح.", "As in the Sahih."),
  q("q4", "asabiyyah", "بماذا وصف النبي ﷺ دعوى العصبية؟", "How did the Prophet ﷺ describe the tribal call?", [["دعوى الجاهلية، ودعوها فإنها منتنة", "The call of Jahiliyyah; leave it, it is rotten"], ["لا بأس بها", "There is no harm in it"], ["هي من الدين", "It is part of the religion"]], 0, "وقال: وأنا بين أظهركم؟", "He said: while I am among you?"),
  q("q5", "asabiyyah", "لماذا لم يأذن النبي ﷺ لعمر بقتل ابن أبي؟", "Why did the Prophet ﷺ not let ʿUmar kill Ibn Ubayy?", [["لئلا يتحدث الناس أن محمدًا يقتل أصحابه", "So people would not say Muhammad kills his companions"], ["لأنه تاب", "He had repented"], ["لأنه كان غائبًا", "He was absent"]], 0, "حرصًا على سمعة الإسلام.", "Out of concern for Islam's reputation."),
  q("q6", "ifk-3", "ماذا كانت أول كلمة قالها النبي ﷺ بعد نزول البراءة؟", "What were the Prophet's ﷺ first words after the acquittal was revealed?", [["يا عائشة، أما الله فقد برأك", "ʿAʾishah, Allah has declared you innocent"], ["قومي إلى أبويك", "Go to your parents"], ["استغفري الله", "Ask Allah's forgiveness"]], 0, "فقالت: لا أحمد إلا الله.", "She said: I praise no one but Allah."),
  q("q7", "hadd", "ما حكم العمري على أحاديث إقامة الحد على ابن أبي؟", "How does al-ʿUmari grade the reports that Ibn Ubayy was flogged?", [["ضعيفة", "Weak"], ["صحيحة", "Sound"], ["متواترة", "Mass-transmitted"]], 0, "والمشهور أنه لم يُحد.", "The well-known view is that he was not."),
  q("q8", "ifk-3", "ماذا فعل أبو بكر بعد نزول آية ﴿ولا يأتل﴾؟", "What did Abu Bakr do after 'Let not those of grace swear…' was revealed?", [["عاد إلى النفقة على مسطح", "He resumed supporting Mistah"], ["هجر مسطحًا", "He shunned Mistah"], ["طلب جلده مرة أخرى", "He asked for him to be flogged again"]], 0, "وكان قريبه.", "Mistah was his relative."),
]);

export const s40 = L(40, "hudaybiyah", "صلح الحديبية", "The Treaty of al-Hudaybiyah", [
  card("hook", "hook", "الصلح الذي سماه الله فتحًا", "The treaty Allah called a victory",
    "خرج المسلمون معتمرين لا يريدون قتالًا، فصُدّوا عن البيت، وعُقد صلح بدا للصحابة فيه إجحاف، حتى قال عمر ما قال. ثم نزلت سورة الفتح. في هذا الدرس: الرؤيا، والطريق، والرسل، وبيعة الرضوان، وبنود الصلح، وأبو جندل وأبو بصير.",
    "The Muslims set out for ʿumrah, wanting no fighting. They were barred from the House, and a treaty was made that seemed unfair to the Companions, so much so that ʿUmar said what he said. Then Surat al-Fath came down. In this lesson: the dream, the route, the envoys, the Pledge of Ridwan, the terms, and Abu Jandal and Abu Basir.",
    []),
  card("dream", "facts", "الرؤيا والخروج", "The dream and the departure",
    "«أري رسول الله صلى الله عليه وسلم في المنام، وهو بالمدينة، أنه دخل هو وأصحابه المسجد الحرام»، فخرج في ذي القعدة سنة ٦هـ «في ألف وأربعمائة، ويقال: ألف وخمسمائة، ولم يخرج معه بسلاح، إلا سلاح المسافر». ويقول العمري: «وساقوا الهدى سبعين» بدنة.",
    "'The Messenger of Allah ﷺ was shown in a dream, while in Madinah, that he and his companions entered the Sacred Mosque.' He set out in Dhu al-Qaʿdah, 6 AH, 'with fourteen hundred, or fifteen hundred it is said, carrying no weapons except a traveller's'. Al-ʿUmari: 'they drove seventy sacrificial camels'.",
    [ci("raheeq_p324_s", "grading_unverified", "أري رسول الله صلى الله عليه وسلم في المنام، وهو بالمدينة، أنه دخل هو وأصحابه المسجد الحرام"), ci("raheeq_p325_s", "grading_unverified", "في ألف وأربعمائة، ويقال: ألف وخمسمائة، ولم يخرج معه بسلاح، إلا سلاح المسافر"), ci("umari_p436_hady", "grading_unverified", "وساقوا الهدى سبعين")],
    [fl("conflict", "العدد: ألف وأربعمائة أو ألف وخمسمائة.", "The number: fourteen hundred or fifteen hundred.")]),
  card("shura", "facts", "الشورى في الطريق", "Consultation on the way",
    "لما بلغه أن قريشًا جمعت له الأحابيش استشار أصحابه، «فقال أبو بكر: الله ورسوله أعلم، إنما جئنا معتمرين، ولم نجئ لقتال أحد»، فمضى. ويقول العمري: وكان النبي ﷺ «كثير الاستشارة لأصحابه». وهمّ خالد بن الوليد بالإغارة عليهم في الصلاة، «ولكن الله أنزل حكم صلاة الخوف، ففاتت الفرصة خالدا.»",
    "When he heard that Quraysh had gathered the Ahabish against him, he consulted his companions, 'and Abu Bakr said: Allah and His Messenger know best; we came only for ʿumrah, not to fight anyone', so he went on. Al-ʿUmari: the Prophet ﷺ 'consulted his companions often'. Khalid ibn al-Walid planned to fall on them during prayer, 'but Allah revealed the ruling of the fear prayer, and Khalid missed his chance.'",
    [ci("raheeq_p325_t", "grading_unverified", "فقال أبو بكر: الله ورسوله أعلم، إنما جئنا معتمرين، ولم نجئ لقتال أحد"), ci("umari_p437_shura", "grading_unverified", "كثير الاستشارة لأصحابه"), ci("raheeq_p325_u", "grading_unverified", "ولكن الله أنزل حكم صلاة الخوف، ففاتت الفرصة خالدا.")],
    [fl("conflict", "أول صلاة خوف: بعسفان في الحديبية عند العمري (ص ٤٣٧)، خلافًا لمن جعلها في ذات الرقاع قبل ذلك.", "The first fear prayer: at ʿUsfan during al-Hudaybiyah per al-ʿUmari (p. 437), against those who put it earlier, at Dhat al-Riqaʿ.")]),
  card("qaswa", "narrative", "«حبسها حابس الفيل»", "'Held back by the One who held back the elephant'",
    "بركت القصواء بثنية المرار، فقالوا: خلأت، فقال ﷺ: «ولكن حبسها حابس الفيل»، ثم قال: «والذي نفسي بيده لا يسألوني خطة يعظمون فيها حرمات الله إلا أعطيتهم إياها». ونزل على ماء قليل، فغرز فيه سهمًا، «فوالله ما زال يجيش لهم بالري حتى صدروا.»",
    "Al-Qaswaʾ knelt at the pass of al-Murar and they said she had balked. He ﷺ said: 'Rather, the One who held back the elephant has held her back', then: 'By Him in whose hand is my soul, they will not ask me for any plan that honours Allah's sanctities but I will grant it.' He camped at a little water and had an arrow planted in it, 'and by Allah it kept gushing with water for them until they had drunk their fill.'",
    [ci("raheeq_p326_s", "grading_unverified", "ولكن حبسها حابس الفيل"), ci("raheeq_p326_t", "grading_unverified", "والذي نفسي بيده لا يسألوني خطة يعظمون فيها حرمات الله إلا أعطيتهم إياها"), ci("raheeq_p326_u", "grading_unverified", "فوالله ما زال يجيش لهم بالري حتى صدروا.")]),
  card("budayl", "facts", "بديل بن ورقاء", "Budayl ibn Warqaʾ",
    "جاء بديل الخزاعي، فقال له ﷺ: «إنا لم نجئ لقتال أحد، ولكنا جئنا معتمرين»، وعرض على قريش هدنة، وإلا قاتلهم حتى تنفرد سالفته. فنقل بديل ذلك إلى قريش.",
    "Budayl of Khuzaʿah came, and he ﷺ told him: 'We have not come to fight anyone; we have come for ʿumrah.' He offered Quraysh a truce, failing which he would fight them until his neck was severed. Budayl carried this to Quraysh.",
    [ci("raheeq_p326_v", "grading_unverified", "إنا لم نجئ لقتال أحد، ولكنا جئنا معتمرين")]),
  card("envoys", "narrative", "الحليس وعروة بن مسعود", "al-Hulays and ʿUrwah ibn Masʿud",
    "لما رأى الحليس الهدي قال: «سبحان الله ما ينبغي لهؤلاء أن يصدوا عن البيت». وجاء عروة بن مسعود، فكان يمد يده إلى لحية النبي ﷺ، فيضربها المغيرة ويقول: «أخر يدك عن لحية رسول الله صلى الله عليه وسلم». ثم رجع إلى قومه فقال: «والله لقد وفدت على الملوك، على قيصر وكسري والنجاشي»، وما رأى ملكًا يعظمه أصحابه كما يعظم أصحاب محمد محمدًا.",
    "When al-Hulays saw the sacrificial animals he said: 'Glory be to Allah, these people should not be barred from the House.' ʿUrwah ibn Masʿud came and kept reaching for the Prophet's ﷺ beard; al-Mughirah would strike his hand and say: 'Keep your hand off the beard of the Messenger of Allah ﷺ.' He went back to his people and said: 'By Allah, I have been sent to kings, to Caesar, Chosroes and the Negus', and he had never seen a king honoured by his men as Muhammad's companions honour Muhammad.",
    [ci("raheeq_p327_s", "grading_unverified", "سبحان الله ما ينبغي لهؤلاء أن يصدوا عن البيت"), ci("raheeq_p327_t", "grading_unverified", "أخر يدك عن لحية رسول الله صلى الله عليه وسلم"), ci("raheeq_p327_u", "grading_unverified", "والله لقد وفدت على الملوك، على قيصر وكسري والنجاشي")]),
  card("youths", "facts", "«وهو الذي كف أيديهم عنكم»", "'It is He who held back their hands from you'",
    "حاول شباب من قريش التسلل ليلًا لإشعال الحرب، «غير أن محمد بن مسلمة قائد الحرس اعتقلهم جميعا.» فعفا عنهم النبي ﷺ رغبة في الصلح، فنزلت الآية.",
    "Young men of Quraysh tried to slip into the camp at night to start a war, 'but Muhammad ibn Maslamah, the commander of the guard, captured them all.' The Prophet ﷺ pardoned them, wanting peace, and the verse was revealed.",
    [ci("raheeq_p328_s", "grading_unverified", "غير أن محمد بن مسلمة قائد الحرس اعتقلهم جميعا.")],
    [fl("conflict", "عددهم: سبعون أو ثمانون في الرحيق، وثلاثون وسبعون وأربعة في روايات ذكرها العمري (ص ٤٤٦).", "Their number: seventy or eighty in al-Raheeq; al-ʿUmari mentions reports of thirty, seventy and four (p. 446).")]),
  card("uthman", "facts", "عثمان سفيرًا", "ʿUthman as envoy",
    "اعتذر عمر لأنه لا عشيرة له بمكة، فأُرسل عثمان، فعرضت عليه قريش الطواف، «وأبي أن يطوف حتى يطوف رسول الله صلى الله عليه وسلم.» ثم احتبسته قريش فشاع أنه قُتل.",
    "ʿUmar excused himself because he had no clan in Makkah to protect him, so ʿUthman was sent. Quraysh offered to let him circle the Kaʿbah, 'and he refused to circle it until the Messenger of Allah ﷺ did.' Then Quraysh detained him, and a rumour spread that he had been killed.",
    [ci("raheeq_p328_t", "grading_unverified", "وأبي أن يطوف حتى يطوف رسول الله صلى الله عليه وسلم.")]),
  card("ridwan", "facts", "بيعة الرضوان", "The Pledge of Ridwan",
    "دعا النبي ﷺ إلى البيعة تحت الشجرة، «وأخذ رسول الله صلى الله عليه وسلم بيد نفسه وقال: هذه عن عثمان.» ويقول العمري: «وكانت البيعة على الموت»، وفي روايات أخرى على ألا يفروا، ولا تعارض. ويقول: «وأول من بادر إلى البيعة» أبو سنان الأسدي.",
    "The Prophet ﷺ called for a pledge under the tree, 'and he took his own hand and said: This is for ʿUthman.' Al-ʿUmari: 'the pledge was to the death'; other reports say it was not to flee, and the two do not conflict. 'The first to hasten to the pledge' was Abu Sinan al-Asadi.",
    [ci("raheeq_p329_s", "grading_unverified", "وأخذ رسول الله صلى الله عليه وسلم بيد نفسه وقال: هذه عن عثمان."), ci("umari_p440_mawt", "grading_unverified", "وكانت البيعة على الموت"), ci("umari_p440_first", "grading_unverified", "وأول من بادر إلى البيعة")],
    [fl("conflict", "على ماذا بايعوا: الموت، أو ألا يفروا، أو الصبر؛ ويجمع العمري بينها (ص ٤٤٠).", "What they pledged: death, not to flee, or steadfastness; al-ʿUmari reconciles them (p. 440).")]),
  card("terms", "facts", "بنود الصلح", "The terms of the treaty",
    "أرسلت قريش سهيل بن عمرو، فاتفقوا على: رجوع المسلمين هذا العام والعمرة في العام القابل ثلاثة أيام، و«وضع الحرب بين الطرفين عشر سنين، يأمن فيها الناس، ويكف بعضهم عن بعض.»، وحرية القبائل في الدخول في أي العهدين، و«من أتي محمدا من قريش من غير إذن وليه ـ أي هاربا منهم ـ رده عليهم، ومن جاء قريشا ممن مع محمد ـ أي هاربا منه ـ لم يرد عليه.»",
    "Quraysh sent Suhayl ibn ʿAmr, and they agreed: the Muslims go back this year and do ʿumrah the next year for three days; 'war is set aside between the two sides for ten years, during which people are safe and hold back from one another'; tribes may join either side's pact; and 'whoever comes to Muhammad from Quraysh without his guardian's permission, that is fleeing them, he returns to them, and whoever of Muhammad's people comes to Quraysh, fleeing him, is not returned.'",
    [ci("raheeq_p329_t", "grading_unverified", "وضع الحرب بين الطرفين عشر سنين، يأمن فيها الناس، ويكف بعضهم عن بعض."), ci("raheeq_p329_u", "grading_unverified", "من أتي محمدا من قريش من غير إذن وليه ـ أي هاربا منهم ـ رده عليهم، ومن جاء قريشا ممن مع محمد ـ أي هاربا منه ـ لم يرد عليه.")]),
  card("writing", "narrative", "كتابة الصحيفة", "Writing the document",
    "أملى النبي ﷺ: بسم الله الرحمن الرحيم، فقال سهيل: «أما الرحمن فوالله لا ندري ما هو؟ ولكن اكتب: باسمك اللهم.» ثم اعترض على «رسول الله»، فقال ﷺ: «إني رسول الله وإن كذبتموني»، وأبى علي أن يمحوها، فمحاها النبي ﷺ بيده. ودخلت خزاعة في عهد النبي ﷺ، وبنو بكر في عهد قريش.",
    "The Prophet ﷺ dictated 'In the name of Allah, the Most Merciful, the Most Compassionate', and Suhayl said: 'As for al-Rahman, by Allah we do not know what it is; write: In Your name, O Allah.' Then he objected to 'Messenger of Allah', and he ﷺ said: 'I am the Messenger of Allah even if you deny me.' ʿAli refused to erase it, so the Prophet ﷺ erased it with his own hand. Khuzaʿah joined the Prophet's ﷺ pact and Banu Bakr joined Quraysh's.",
    [ci("raheeq_p330_s", "grading_unverified", "أما الرحمن فوالله لا ندري ما هو؟ ولكن اكتب: باسمك اللهم."), ci("raheeq_p330_t", "grading_unverified", "إني رسول الله وإن كذبتموني")]),
  card("abu-jandal", "narrative", "أبو جندل", "Abu Jandal",
    "جاء أبو جندل بن سهيل يرسف في قيوده، فطلب سهيل رده، فرُدّ، وهو يصرخ: «يا معشر المسلمين، أأرد إلى المشركين يفتنوني في ديني؟» فقال ﷺ: «يا أبا جندل، اصبر واحتسب، فإن الله جاعل لك ولمن معك من المستضعفين فرجا ومخرجا».",
    "Abu Jandal ibn Suhayl came shuffling in his chains. Suhayl demanded his return and he was handed back, crying: 'Muslims, am I to be sent back to the idolaters to be tormented for my religion?' He ﷺ said: 'Abu Jandal, be patient and seek reward; Allah will make for you and the weak ones with you a relief and a way out.'",
    [ci("raheeq_p330_u", "grading_unverified", "يا معشر المسلمين، أأرد إلى المشركين يفتنوني في ديني؟"), ci("raheeq_p330_v", "grading_unverified", "يا أبا جندل، اصبر واحتسب، فإن الله جاعل لك ولمن معك من المستضعفين فرجا ومخرجا")]),
  card("umm-salamah", "facts", "مشورة أم سلمة", "Umm Salamah's advice",
    "أمرهم بالنحر ثلاثًا فلم يقم أحد، ويعلل العمري ذلك: «فكأنهم كانوا يأملون العودة عن الصلح». فقالت أم سلمة: «اخرج، ثم لا تكلم أحدا كلمة حتى تنحر بدنك، وتدعو حالقك فيحلقك»، ففعل، فقاموا فنحروا. «ودعا رسول الله صلى الله عليه وسلم للمحلقين ثلاثا بالمغفرة وللمقصرين مرة.»",
    "He told them three times to sacrifice and no one stood. Al-ʿUmari explains: 'it was as if they still hoped the treaty would be undone'. Umm Salamah said: 'Go out and do not say a word to anyone until you sacrifice your camels and call your barber to shave you.' He did, and they rose and sacrificed. 'The Messenger of Allah ﷺ prayed for forgiveness for those who shaved three times, and once for those who trimmed.'",
    [ci("umari_p446_hope", "grading_unverified", "فكأنهم كانوا يأملون العودة عن الصلح"), ci("raheeq_p331_s", "grading_unverified", "اخرج، ثم لا تكلم أحدا كلمة حتى تنحر بدنك، وتدعو حالقك فيحلقك"), ci("raheeq_p331_t", "grading_unverified", "ودعا رسول الله صلى الله عليه وسلم للمحلقين ثلاثا بالمغفرة وللمقصرين مرة.")]),
  card("women", "facts", "المهاجرات", "The women emigrants",
    "جاءت نسوة مؤمنات فطلب أولياؤهن ردهن، فأبى؛ لأن نص البند كان في الرجال، «فلم تدخل النساء في العقد رأسا.» ونزلت آية الامتحان في سورة الممتحنة.",
    "Believing women came and their guardians demanded them back. He refused, because the clause spoke of men, 'so women were not included in the agreement at all.' The verse of examining them in Surat al-Mumtahanah was revealed.",
    [ci("raheeq_p331_u", "grading_unverified", "فلم تدخل النساء في العقد رأسا.")]),
  card("analysis", "context", "لماذا كان فتحًا؟", "Why it was a victory",
    "يحلل المباركفوري البنود: فالصلح اعتراف بقوة المسلمين، وحرية الدعوة أثمرت؛ «فبينما كان عدد المسلمين لا يزيد على ثلاثة آلاف قبل الهدنة صار عدد الجيش الإسلامي في سنتين عند فتح مكة عشرة آلاف.» وأما رد الفار فقال ﷺ: «إنه من ذهب منا إليهم فأبعده الله.»",
    "Al-Mubarakpuri analyses the terms: the treaty itself recognised the Muslims' strength, and freedom to preach bore fruit: 'whereas the Muslims numbered no more than three thousand before the truce, within two years the Muslim army at the Conquest of Makkah was ten thousand.' As for returning those who fled, he ﷺ said: 'Whoever of us goes over to them, Allah has put him far away.'",
    [ci("raheeq_p332_s", "grading_unverified", "فبينما كان عدد المسلمين لا يزيد على ثلاثة آلاف قبل الهدنة صار عدد الجيش الإسلامي في سنتين عند فتح مكة عشرة آلاف."), ci("raheeq_p332_t", "grading_unverified", "إنه من ذهب منا إليهم فأبعده الله.")],
    [fl("gap", "رقم «ثلاثة آلاف» تقدير من المؤلف، لا رواية.", "The 'three thousand' figure is the author's estimate, not a report.")]),
  card("umar", "narrative", "مراجعة عمر", "ʿUmar's objection",
    "قال عمر: ففيم نعطي الدنية في ديننا؟ فقال ﷺ: «يا ابن الخطاب، إني رسول الله ولست أعصيه، وهو ناصري ولن يضيعني أبدا.» وأجابه أبو بكر بمثل ذلك وزاد: «حتى تموت، فوالله إنه لعلى الحق.» ويقول العمري: «والواقع أن المسلمين تذمروا من هذه الاتفاقية». ثم ندم عمر وقال: «مازلت أتصدق وأصوم وأصلي وأعتق من الذي صنعت يومئذ».",
    "ʿUmar said: 'Then why should we accept humiliation in our religion?' He ﷺ said: 'Son of al-Khattab, I am the Messenger of Allah and I do not disobey Him; He is my helper and will never abandon me.' Abu Bakr gave him the same answer and added: 'hold to his stirrup until you die, for by Allah he is in the right.' Al-ʿUmari: 'in fact the Muslims were unhappy with this agreement'. Later ʿUmar regretted it and said: 'I kept giving charity, fasting, praying and freeing slaves because of what I did that day'.",
    [ci("raheeq_p333_s", "grading_unverified", "يا ابن الخطاب، إني رسول الله ولست أعصيه، وهو ناصري ولن يضيعني أبدا."), ci("raheeq_p333_t", "grading_unverified", "حتى تموت، فوالله إنه لعلى الحق."), ci("umari_p443_tadhammur", "grading_unverified", "والواقع أن المسلمين تذمروا من هذه الاتفاقية"), ci("raheeq_p334_t", "grading_unverified", "مازلت أتصدق وأصوم وأصلي وأعتق من الذي صنعت يومئذ")]),
  card("fath", "facts", "نزول سورة الفتح", "The revelation of Surat al-Fath",
    "نزلت ﴿إنا فتحنا لك فتحا مبينا﴾، فأرسل إلى عمر فأقرأه إياها، «فقال: يا رسول الله، أو فتح هو؟ قال: نعم. فطابت نفسه ورجع.» وعند العمري قال ﷺ لرجل سأله: «نعم والذي نفسي بيده إنه لفتح».",
    "'Indeed We have given you a clear victory' was revealed. He sent for ʿUmar and recited it to him, 'and he said: Messenger of Allah, is it a victory? He said: Yes. So he was content and went back.' In al-ʿUmari he ﷺ told a man who asked: 'Yes, by Him in whose hand is my soul, it is a victory.'",
    [ci("raheeq_p334_s", "grading_unverified", "فقال: يا رسول الله، أو فتح هو؟ قال: نعم. فطابت نفسه ورجع."), ci("umari_p449_fath", "grading_unverified", "نعم والذي نفسي بيده إنه لفتح")]),
  card("abu-basir", "narrative", "أبو بصير", "Abu Basir",
    "فرّ أبو بصير إلى المدينة فردّه النبي ﷺ وفاءً بالعهد، فقتل أحد الحارسين ورجع فقال: «قد والله أوفي الله ذمتك، قد رددتني إليهم، ثم أنجاني الله منهم». فلحق بسيف البحر، وانضم إليه أبو جندل وغيره، فاعترضوا عير قريش حتى طلبت قريش من النبي ﷺ أن يؤويهم. ويستنبط العمري منها مبدأ: «قد يسع الفرد مالا يسع الجماعة».",
    "Abu Basir fled to Madinah and the Prophet ﷺ handed him back to keep the treaty. He killed one of his two guards, came back and said: 'By Allah, Allah has fulfilled your obligation; you returned me to them, then Allah saved me from them.' He went to the coast, Abu Jandal and others joined him, and they raided Quraysh's caravans until Quraysh asked the Prophet ﷺ to take them in. Al-ʿUmari draws from it the principle: 'an individual may do what the community may not'.",
    [ci("raheeq_p334_u", "grading_unverified", "قد والله أوفي الله ذمتك، قد رددتني إليهم، ثم أنجاني الله منهم"), ci("umari_p452_fard", "grading_unverified", "قد يسع الفرد مالا يسع الجماعة")]),
  card("heroes", "facts", "إسلام خالد وعمرو", "Khalid and ʿAmr accept Islam",
    "في سنة ٧هـ أسلم عمرو بن العاص وخالد بن الوليد وعثمان بن طلحة، فقال ﷺ: «إن مكـة قد ألقت إلينا أفلاذ كبدها.»",
    "In 7 AH ʿAmr ibn al-ʿAs, Khalid ibn al-Walid and ʿUthman ibn Talhah accepted Islam, and he ﷺ said: 'Makkah has thrown us the pieces of her liver.'",
    [ci("raheeq_p335_s", "grading_unverified", "إن مكـة قد ألقت إلينا أفلاذ كبدها.")],
    [fl("gap", "لم نتحقق من إسناد هذه العبارة؛ الرحيق يسوقها دون عزو.", "We have not verified the chain of this saying; al-Raheeq gives it without a reference.")]),
  card("reflection", "reflection", "حين يغيب عنا وجه الحكمة", "When the wisdom is hidden from us",
    "تأمل (ليس رواية): رأى الصحابة في الصلح ضيمًا، ثم صار أعظم فتح. والدرس: التسليم لأمر الله ورسوله، ولو لم تظهر الحكمة في حينها.",
    "Reflection (not a source claim): the Companions saw injustice in the treaty, and it became the greatest opening. The lesson is submission to the command of Allah and His Messenger, even when the wisdom is not clear at the time.",
    []),
  card("summary", "summary", "خلاصة الدرس", "Lesson summary",
    "ذو القعدة ٦هـ: خرج نحو ١٤٠٠ معتمرين، فصدتهم قريش. بركت القصواء، وتوالت الرسل، وبويع تحت الشجرة لما شاع قتل عثمان. ثم عُقد الصلح مع سهيل: رجوع هذا العام، وهدنة عشر سنين، وحرية التحالف، ورد الفار من قريش. ورُد أبو جندل، ونحروا بمشورة أم سلمة، ونزلت سورة الفتح، ثم أنهى أبو بصير وأصحابه شرط الرد عمليًا.",
    "Dhu al-Qaʿdah 6 AH: about 1,400 set out for ʿumrah and Quraysh barred them. Al-Qaswaʾ knelt, envoys came and went, and the pledge was taken under the tree when ʿUthman was rumoured killed. Then the treaty was made with Suhayl: go back this year, a ten-year truce, freedom to make alliances, and returning those who fled Quraysh. Abu Jandal was handed back, they sacrificed on Umm Salamah's advice, Surat al-Fath was revealed, and Abu Basir and his men in practice ended the return clause.",
    []),
], [
  q("q1", "qaswa", "ماذا قال النبي ﷺ لما بركت القصواء؟", "What did the Prophet ﷺ say when al-Qaswaʾ knelt?", [["حبسها حابس الفيل", "The One who held back the elephant has held her"], ["أصابها مرض", "She is sick"], ["ارجعوا إلى المدينة", "Go back to Madinah"]], 0, "ثم زجرها فوثبت.", "Then he urged her and she rose."),
  q("q2", "envoys", "ماذا قال عروة بن مسعود لقريش بعد رجوعه؟", "What did ʿUrwah ibn Masʿud tell Quraysh on his return?", [["ما رأى ملكًا يعظمه أصحابه كتعظيم أصحاب محمد محمدًا", "He had never seen a king honoured as Muhammad's companions honour him"], ["إن المسلمين ضعفاء", "The Muslims are weak"], ["إنه سيقاتلكم الليلة", "He will attack you tonight"]], 0, "وقد وفد على قيصر وكسرى والنجاشي.", "He had visited Caesar, Chosroes and the Negus."),
  q("q3", "ridwan", "لماذا كانت بيعة الرضوان؟", "Why was the Pledge of Ridwan taken?", [["لما شاع أن عثمان قُتل", "Because of the rumour that ʿUthman had been killed"], ["لدخول مكة بالقوة", "To enter Makkah by force"], ["لاختيار أمير", "To choose a leader"]], 0, "وبايع النبي ﷺ عن عثمان بيده.", "The Prophet ﷺ pledged for ʿUthman with his own hand."),
  q("q4", "terms", "كم كانت مدة وضع الحرب في الصلح؟", "How long was the truce in the treaty?", [["عشر سنين", "Ten years"], ["سنتان", "Two years"], ["ثلاثة أيام", "Three days"]], 0, "يأمن فيها الناس.", "During which people are safe."),
  q("q5", "writing", "من محا لفظ «رسول الله» من الصحيفة؟", "Who erased 'Messenger of Allah' from the document?", [["النبي ﷺ بيده", "The Prophet ﷺ with his own hand"], ["علي", "ʿAli"], ["سهيل", "Suhayl"]], 0, "أبى علي أن يمحوه.", "ʿAli refused to erase it."),
  q("q6", "umm-salamah", "بماذا أشارت أم سلمة؟", "What did Umm Salamah advise?", [["أن يخرج فينحر ويحلق دون أن يكلم أحدًا", "That he go out, sacrifice and shave without speaking to anyone"], ["أن يرجع إلى المدينة", "That he return to Madinah"], ["أن يقاتل قريشًا", "That he fight Quraysh"]], 0, "فلما رأوه فعلوا.", "When they saw him, they did the same."),
  q("q7", "women", "لماذا لم تُرد المهاجرات؟", "Why were the women emigrants not returned?", [["لأن البند نص على الرجال فلم تدخل النساء", "The clause named men, so women were not included"], ["لأن قريشًا لم تطلبهن", "Quraysh did not ask"], ["لأن الصلح أُلغي", "The treaty was cancelled"]], 0, "ونزلت آية الامتحان.", "The verse of examining them came down."),
  q("q8", "abu-basir", "أي مبدأ يستنبطه العمري من قصة أبي بصير؟", "What principle does al-ʿUmari draw from Abu Basir's story?", [["قد يسع الفرد ما لا يسع الجماعة", "An individual may do what the community may not"], ["الغاية تبرر الوسيلة", "The end justifies the means"], ["لا عهد مع المشركين", "No treaty with idolaters"]], 0, "لأنه كان خارج سلطة الدولة.", "Because he was outside the state's authority."),
]);

export const s41 = L(41, "letters", "مكاتبة الملوك والأمراء", "Letters to the kings and rulers", [
  card("hook", "hook", "رسالة إلى العالم", "A message to the world",
    "بعد الحديبية أمنت الجبهة مع قريش، فكتب النبي ﷺ إلى الملوك يدعوهم إلى الإسلام: النجاشي، والمقوقس، وكسرى، وقيصر، وأمراء العرب. في هذا الدرس: الكتب، ورسلها، وردود الملوك، وما يثبت من نصوصها وما لا يثبت.",
    "After al-Hudaybiyah the front with Quraysh was quiet, and the Prophet ﷺ wrote to kings inviting them to Islam: the Negus, al-Muqawqis, Chosroes, Caesar and the Arab princes. In this lesson: the letters, their carriers, the kings' replies, and which texts are established and which are not.",
    []),
  card("new-phase", "context", "طور جديد", "A new phase",
    "يقول المباركفوري: «إن صلح الحديبية كان بداية طور جديد في حياة الإسلام والمسلمين»؛ إذ انسحبت قريش أقوى الأحزاب من الحرب. ويقول العمري: «ولا شك أن مكاتبة الملوك خارج جزيرة العرب تعبير عملي عن عالمية الرسالة الإسلامية».",
    "Al-Mubarakpuri: 'the Treaty of al-Hudaybiyah was the start of a new phase in the life of Islam and the Muslims', since Quraysh, the strongest of the Confederates, left the war. Al-ʿUmari: 'there is no doubt that writing to kings outside Arabia was a practical expression of the universality of the Islamic message'.",
    [ci("raheeq_p336_s", "grading_unverified", "إن صلح الحديبية كان بداية طور جديد في حياة الإسلام والمسلمين"), ci("umari_p455_alamiyyah", "grading_unverified", "ولا شك أن مكاتبة الملوك خارج جزيرة العرب تعبير عملي عن عالمية الرسالة الإسلامية")],
    [fl("conflict", "تاريخ إرسال الكتب: آخر سنة ٦ أو المحرم سنة ٧، ويوفق ابن حجر بينهما (العمري ص ٤٥٥).", "When the letters were sent: end of year 6 or Muharram year 7; Ibn Hajar reconciles the two (al-ʿUmari p. 455).")]),
  card("seal", "facts", "الخاتم", "The seal",
    "قيل له إن الملوك لا يقرؤون كتابًا إلا مختومًا، «فاتخذ النبي صلى الله عليه وسلم خاتما من فضة، نقشه: محمد رسول الله صلى الله عليه وسلم». ويثبته العمري: «فاتخذ خاتماً من فضة ونقشه : محمد رسول الله»، ويرى فيه مرونة في الإفادة من الرسوم المعاصرة.",
    "He was told that kings read no letter unless it is sealed, 'so the Prophet ﷺ took a silver seal ring engraved: Muhammad the Messenger of Allah ﷺ'. Al-ʿUmari confirms it ('he took a silver ring and engraved it: Muhammad the Messenger of Allah') and sees in it a flexible use of the customs of the time.",
    [ci("raheeq_p337_s", "grading_unverified", "فاتخذ النبي صلى الله عليه وسلم خاتما من فضة، نقشه: محمد رسول الله صلى الله عليه وسلم"), ci("umari_p459_seal", "grading_unverified", "فاتخذ خاتماً من فضة ونقشه : محمد رسول الله")]),
  card("authenticity", "context", "ما الذي يثبت من نصوص الكتب؟", "Which letter texts are established?",
    "هذه أهم ملاحظة في الدرس: يقول العمري عن كتاب هرقل في البخاري: «وهو النص الوحيد الذي ثبتت صحته»، ويكرر أنه «هو الوحيد الذي يصح حديثيا». وعن كتاب كسرى: «وأما نص الكتاب إلى كسرى فلم يثبت من طريق صحيحة». ومع ذلك: «وهذه الملاحظات لا تقوى على هدم الأساس التاريخي لوجود الرسائل».",
    "This is the most important point in the lesson. Al-ʿUmari says of the letter to Heraclius in al-Bukhari: 'it is the only text whose authenticity is established', and repeats that it 'is the only one sound by hadith standards'. Of the letter to Chosroes: 'the text of the letter to Chosroes is not established by a sound route'. Even so: 'these objections are not strong enough to demolish the historical basis for the letters' existence'.",
    [ci("umari_p456_only", "grading_unverified", "وهو النص الوحيد الذي ثبتت صحته"), ci("umari_p459_hadithi", "grading_unverified", "هو الوحيد الذي يصح حديثيا"), ci("umari_p458_kisra", "grading_unverified", "وأما نص الكتاب إلى كسرى فلم يثبت من طريق صحيحة"), ci("umari_p460_orient", "grading_unverified", "وهذه الملاحظات لا تقوى على هدم الأساس التاريخي لوجود الرسائل")],
    [fl("weak", "نصوص الكتب إلى النجاشي والمقوقس وكسرى والمنذر وهوذة والحارث وملكي عمان، كما في الرحيق، لا تثبت حديثيًا عند العمري؛ الثابت كتاب هرقل وحده.", "The texts of the letters to the Negus, al-Muqawqis, Chosroes, al-Mundhir, Hawdhah, al-Harith and the kings of ʿUman, as given in al-Raheeq, are not established by hadith standards per al-ʿUmari; only the letter to Heraclius is.")]),
  card("najashi", "facts", "الكتاب إلى النجاشي", "The letter to the Negus",
    "حمله عمرو بن أمية الضمري. ويناقش المباركفوري النصوص المروية: «وقد ذكر الطبري نص الكتاب، ولكن النظر الدقيق في ذلك النص، يفيد أنه ليس بنص الكتاب الذي كتبه صلى الله عليه وسلم بعد الحديبية»، ويعترف بأن ترتيبه للنصوص اجتهاد: «وهذا الترتيب ليس عندي عليه دليل قطعي سوي الشهادات الداخلية التي تؤديها نصوص هذه الكتب.» ويقول العمري عن نص ابن إسحاق: «فقد أورده ابن إسحق بدون إسناد».",
    "ʿAmr ibn Umayyah al-Damri carried it. Al-Mubarakpuri discusses the reported texts: 'al-Tabari gives the text of the letter, but close study shows it is not the letter he ﷺ wrote after al-Hudaybiyah'. He admits his own ordering of the texts is a judgement: 'I have no decisive proof for this ordering beyond the internal evidence of the texts.' Al-ʿUmari on Ibn Ishaq's text: 'Ibn Ishaq gave it without a chain'.",
    [ci("raheeq_p337_t", "grading_unverified", "وقد ذكر الطبري نص الكتاب، ولكن النظر الدقيق في ذلك النص، يفيد أنه ليس بنص الكتاب الذي كتبه صلى الله عليه وسلم بعد الحديبية"), ci("raheeq_p339_s", "grading_unverified", "وهذا الترتيب ليس عندي عليه دليل قطعي سوي الشهادات الداخلية التي تؤديها نصوص هذه الكتب."), ci("umari_p458_najashi", "grading_unverified", "فقد أورده ابن إسحق بدون إسناد")],
    [fl("no_chain", "نص الكتاب إلى النجاشي غير ثابت؛ وفيه ثلاثة نصوص مختلفة (الطبري، والبيهقي عن ابن إسحاق، ووثيقة حميد الله).", "The text of the letter to the Negus is not established; there are three different texts (al-Tabari, al-Bayhaqi from Ibn Ishaq, and Hamidullah's document).")]),
  card("najashi-reply", "facts", "إسلام النجاشي ووفاته", "The Negus's Islam and death",
    "يذكر الرحيق أن النجاشي لما بلغه الكتاب «أخذه النجاشي، ووضعه على عينه، ونزل عن سريره على الأرض، وأسلم على يد جعفر بن أبي طالب». وتوفي سنة ٩هـ، «ونعاه النبي صلى الله عليه وسلم يوم وفاته، وصلي عليه صلاة الغائب».",
    "Al-Raheeq says that when the letter reached him, 'the Negus took it, placed it on his eye, came down from his throne to the ground, and accepted Islam at the hands of Jaʿfar ibn Abi Talib'. He died in 9 AH, 'and the Prophet ﷺ announced his death on the day he died and prayed the funeral prayer in absence for him'.",
    [ci("raheeq_p339_t", "grading_unverified", "أخذه النجاشي، ووضعه على عينه، ونزل عن سريره على الأرض، وأسلم على يد جعفر بن أبي طالب"), ci("raheeq_p339_u", "grading_unverified", "ونعاه النبي صلى الله عليه وسلم يوم وفاته، وصلي عليه صلاة الغائب")],
    [fl("gap", "نص رد النجاشي في الرحيق لم يُرو بإسناد صحيح عند العمري (ص ٤٥٨).", "The text of the Negus's reply in al-Raheeq was not reported with a sound chain per al-ʿUmari (p. 458)."), fl("conflict", "يذكر العمري أن النجاشي الذي كُتب إليه في رواية مسلم ليس النجاشي الذي أسلم.", "Al-ʿUmari notes that, per Muslim's report, the Negus who was written to is not the one who accepted Islam.")]),
  card("muqawqis", "narrative", "حاطب والمقوقس", "Hatib and al-Muqawqis",
    "حمل حاطب بن أبي بلتعة الكتاب إلى المقوقس، فقال له: «إنه كان قبلك رجل يزعم أنه الرب الأعلى، فأخذه الله نكال الآخرة والأولى». فقال المقوقس: «إني قد نظرت في أمر هذا النبي، فوجدته لا يأمر بمزهود فيه. ولا ينهي عن مرغوب فيه»، ولم يسلم، وأهدى جاريتين: «والجاريتان مارية، وسيرين».",
    "Hatib ibn Abi Baltaʿah carried the letter to al-Muqawqis and said to him: 'Before you there was a man who claimed to be the supreme lord, and Allah seized him as an example in the next life and this one.' Al-Muqawqis said: 'I have looked into this prophet's affair and found he commands nothing to be shunned and forbids nothing to be desired', but he did not accept Islam. He sent two slave women: 'the two were Mariyah and Sirin'.",
    [ci("raheeq_p340_s", "grading_unverified", "إنه كان قبلك رجل يزعم أنه الرب الأعلى، فأخذه الله نكال الآخرة والأولى"), ci("raheeq_p340_t", "grading_unverified", "إني قد نظرت في أمر هذا النبي، فوجدته لا يأمر بمزهود فيه. ولا ينهي عن مرغوب فيه"), ci("raheeq_p341_s", "grading_unverified", "والجاريتان مارية، وسيرين")],
    [fl("gap", "الحوار بين حاطب والمقوقس في الرحيق دون إسناد؛ ونصوص كتب المقوقس لم تثبت حديثيًا عند العمري.", "The dialogue between Hatib and al-Muqawqis is in al-Raheeq without a chain; al-ʿUmari says the texts of the letters to al-Muqawqis are not established by hadith standards.")]),
  card("kisra", "facts", "كسرى يمزق الكتاب", "Chosroes tears up the letter",
    "حمله عبد الله بن حذافة السهمي، «فلما قرئ الكتاب على كسرى مزقه»، فقال ﷺ: «مزق الله ملكه، وقد كان كما قال». فقد قتله ابنه شيرويه، فلما بلغ ذلك باذان عامله على اليمن «وكان ذلك سببا في إسلام باذان ومن معه من أهل فارس باليمن.»",
    "ʿAbdullah ibn Hudhafah al-Sahmi carried it, 'and when the letter was read to Chosroes, he tore it up'. He ﷺ said: 'May Allah tear up his kingdom', 'and it was as he said'. His son Shirawayh killed him, and when this reached Badhan, his governor in Yemen, 'that was the reason Badhan and the Persians with him in Yemen accepted Islam.'",
    [ci("raheeq_p341_t", "grading_unverified", "فلما قرئ الكتاب على كسرى مزقه"), ci("raheeq_p341_u", "grading_unverified", "مزق الله ملكه، وقد كان كما قال"), ci("raheeq_p342_s", "grading_unverified", "وكان ذلك سببا في إسلام باذان ومن معه من أهل فارس باليمن.")],
    [fl("gap", "أصل التمزيق والدعاء في البخاري كما يذكر العمري (ص ٤٥٨)، أما قصة رسولي باذان فلم نتحقق من إسنادها.", "The tearing up and the prayer against him are in al-Bukhari per al-ʿUmari (p. 458); we have not verified the chain of the story of Badhan's two messengers.")]),
  card("heraclius-letter", "facts", "الكتاب إلى هرقل", "The letter to Heraclius",
    "روى البخاري نصه، وفيه: «أسلم تسلم، أسلم يؤتك الله أجرك مرتين، فإن توليت فإن عليك إثم الأريسيين»، ثم آية آل عمران ﴿قل يا أهل الكتاب تعالوا إلى كلمة سواء﴾. وحمله دحية الكلبي إلى عظيم بصرى.",
    "Al-Bukhari reports its text, which includes: 'Accept Islam and you will be safe; accept Islam and Allah will give you your reward twice; if you turn away, the sin of the peasants is upon you', then the verse of Al ʿImran: 'O People of the Book, come to a word common between us and you'. Dihyah al-Kalbi carried it to the governor of Busra.",
    [ci("raheeq_p342_t", "grading_unverified", "أسلم تسلم، أسلم يؤتك الله أجرك مرتين، فإن توليت فإن عليك إثم الأريسيين")],
    [fl("gap", "نقلنا النص من الرحيق عن البخاري؛ لم نطابقه بنسخة من صحيح البخاري.", "We took the text from al-Raheeq quoting al-Bukhari; we have not matched it against a copy of Sahih al-Bukhari.")]),
  card("abu-sufyan-1", "narrative", "هرقل يسأل أبا سفيان", "Heraclius questions Abu Sufyan",
    "استدعى هرقل تجار قريش وفيهم أبو سفيان فسأل: «أيكم أقرب نسبا بهذا الرجل الذي يزعم أنه نبي؟». قال أبو سفيان: «فو الله لولا الحياء من أن يأثروا على كذبا لكذبت عليه.» فسأله عن نسبه، ومن تبعه، وهل يرتد أحد، وهل يغدر، وبم يأمر.",
    "Heraclius summoned Quraysh traders, Abu Sufyan among them, and asked: 'Which of you is closest in lineage to this man who claims to be a prophet?' Abu Sufyan said: 'By Allah, had I not been ashamed that they would report a lie from me, I would have lied about him.' Heraclius asked about his lineage, who followed him, whether anyone left his religion, whether he betrayed, and what he commanded.",
    [ci("raheeq_p342_u", "grading_unverified", "أيكم أقرب نسبا بهذا الرجل الذي يزعم أنه نبي؟"), ci("raheeq_p342_v", "grading_unverified", "فو الله لولا الحياء من أن يأثروا على كذبا لكذبت عليه.")]),
  card("abu-sufyan-2", "narrative", "استنتاج هرقل", "Heraclius's conclusion",
    "عقّب هرقل على كل جواب، فقال في الردة: «وكذلك الإيمان حين تخالط بشاشته القلوب.» ثم قال: «فإن كان ما تقول حقا فسيملك موضع قدمي هاتين». وخرج أبو سفيان يقول: لقد أمِر أمر ابن أبي كبشة، «فما زلت موقنا بأمر رسول الله صلى الله عليه وسلم أنه سيظهر حتى أدخل الله على الإسلام.»",
    "Heraclius commented on each answer. On apostasy he said: 'So is faith when its delight mixes with the hearts.' Then: 'If what you say is true, he will rule the ground beneath these two feet of mine.' Abu Sufyan left saying that Ibn Abi Kabshah's affair had grown great, 'and I remained certain that the Messenger of Allah ﷺ would prevail, until Allah brought Islam into my heart.'",
    [ci("raheeq_p343_s", "grading_unverified", "وكذلك الإيمان حين تخالط بشاشته القلوب."), ci("raheeq_p343_t", "grading_unverified", "فإن كان ما تقول حقا فسيملك موضع قدمي هاتين"), ci("raheeq_p343_u", "grading_unverified", "فما زلت موقنا بأمر رسول الله صلى الله عليه وسلم أنه سيظهر حتى أدخل الله على الإسلام.")]),
  card("hisma", "facts", "سرية حسمى", "The Hisma expedition",
    "نُهب دحية في طريق رجوعه بحسمى، فبعث النبي ﷺ زيد بن حارثة إلى جذام، ثم رد الغنائم لما احتج زيد بن رفاعة. ويقول المؤلف: «وعامة أهل المغازي يذكرون هذه السرية قبل الحديبية، وهو خطأ واضح».",
    "Dihyah was robbed on his way back at Hisma, so the Prophet ﷺ sent Zayd ibn Harithah against Judham; then he returned the spoils when Zayd ibn Rifaʿah protested. The author says: 'most Maghazi writers place this expedition before al-Hudaybiyah, which is a clear error'.",
    [ci("raheeq_p344_s", "grading_unverified", "وعامة أهل المغازي يذكرون هذه السرية قبل الحديبية، وهو خطأ واضح")],
    [fl("conflict", "تاريخ السرية: قبل الحديبية عند عامة أهل المغازي، وبعدها عند المؤلف وابن القيم.", "The expedition's date: before al-Hudaybiyah per most Maghazi writers, after it per the author and Ibn al-Qayyim.")]),
  card("mundhir", "facts", "المنذر بن ساوى", "al-Mundhir ibn Sawa",
    "حمل العلاء بن الحضرمي الكتاب إلى المنذر حاكم البحرين، فأسلم بعض أهلها وكره بعضهم، فجاء في الجواب: «ومن أقام على يهودية أو مجوسية فعليه الجزية.»",
    "Al-ʿAlaʾ ibn al-Hadrami carried the letter to al-Mundhir, ruler of al-Bahrayn. Some of its people accepted Islam and some disliked it, and the reply said: 'whoever stays on Judaism or Zoroastrianism owes the jizyah.'",
    [ci("raheeq_p344_t", "grading_unverified", "ومن أقام على يهودية أو مجوسية فعليه الجزية.")],
    [fl("weak", "نص الكتاب غير ثابت حديثيًا عند العمري.", "The letter's text is not established by hadith standards per al-ʿUmari.")]),
  card("hawdhah-harith", "facts", "هوذة والحارث الغساني", "Hawdhah and al-Harith al-Ghassani",
    "طلب هوذة صاحب اليمامة أن يُجعل له بعض الأمر، فقال ﷺ: «لو سألني قطعة من الأرض ما فعلت، باد، وباد ما في يديه.» ورمى الحارث بن أبي شمر صاحب دمشق بالكتاب وقال: «من ينزع ملكي مني؟ أنا سائر إليه».",
    "Hawdhah, ruler of al-Yamamah, asked to be given a share of authority, and he ﷺ said: 'If he asked me for a strip of land I would not do it; he is finished, and so is what he holds.' Al-Harith ibn Abi Shimr, ruler of Damascus, threw the letter down and said: 'Who will take my kingdom from me? I will march against him.'",
    [ci("raheeq_p345_s", "grading_unverified", "لو سألني قطعة من الأرض ما فعلت، باد، وباد ما في يديه."), ci("raheeq_p345_t", "grading_unverified", "من ينزع ملكي مني؟ أنا سائر إليه")],
    [fl("weak", "نصوص الكتابين والردين غير ثابتة حديثيًا عند العمري.", "The texts of both letters and replies are not established by hadith standards per al-ʿUmari.")]),
  card("oman", "narrative", "عمرو بن العاص في عمان", "ʿAmr ibn al-ʿAs in ʿUman",
    "حمل عمرو الكتاب إلى جيفر وعبد ابني الجلندى، فحاوره عبد طويلًا وقال: «إنه ليس من خصلة في رجل أفضح له من الكذب.» ثم «فأجاب إلى الإسلام هو وأخوه جميعا، وصدقا النبي صلى الله عليه وسلم». ويقول المؤلف عن التاريخ: «والأغلب أنه كان بعد الفتح.»",
    "ʿAmr carried the letter to Jayfar and ʿAbd, the sons of al-Julanda. ʿAbd questioned him at length and said: 'there is no trait more disgraceful in a man than lying.' Then 'he and his brother both accepted Islam and believed the Prophet ﷺ'. On the date the author says: 'most likely it was after the Conquest.'",
    [ci("raheeq_p346_s", "grading_unverified", "إنه ليس من خصلة في رجل أفضح له من الكذب."), ci("raheeq_p347_t", "grading_unverified", "فأجاب إلى الإسلام هو وأخوه جميعا، وصدقا النبي صلى الله عليه وسلم"), ci("raheeq_p347_s", "grading_unverified", "والأغلب أنه كان بعد الفتح.")],
    [fl("gap", "لم نتحقق من إسناد القصة الطويلة؛ والمؤلف يرجّح تأخرها إلى ما بعد الفتح.", "We have not verified the chain of this long story; the author thinks it came later, after the Conquest.")]),
  card("reflection", "reflection", "الحكمة في الخطاب", "Wisdom in how he addressed them",
    "تأمل: يلاحظ العمري أن كتاب هرقل جمع بين الصراحة في الدعوة واحترام المخاطب بلقب «عظيم الروم»، والترغيب بالأجر مرتين، والترهيب من حمل إثم قومه. وهذا نموذج للدعوة بالحكمة.",
    "Reflection: al-ʿUmari notes that the letter to Heraclius combined a clear call with respect for the addressee ('the great one of the Romans'), the promise of a double reward, and the warning that he would carry his people's sin. It is a model of calling with wisdom.",
    []),
  card("summary", "summary", "خلاصة الدرس", "Lesson summary",
    "بعد الحديبية اتخذ النبي ﷺ خاتمًا وكتب إلى الملوك: النجاشي (أسلم في الرحيق)، والمقوقس (أهدى مارية ولم يسلم)، وكسرى (مزق الكتاب فمُزق ملكه)، وهرقل (سأل أبا سفيان وأقرّ ولم يسلم)، والمنذر، وهوذة، والحارث، وملكي عمان (أسلما). والثابت حديثيًا من النصوص كتاب هرقل وحده، ولا ينفي ذلك أصل إرسال الكتب.",
    "After al-Hudaybiyah the Prophet ﷺ took a seal and wrote to the kings: the Negus (who became Muslim, per al-Raheeq), al-Muqawqis (who sent Mariyah but did not become Muslim), Chosroes (who tore the letter, and his kingdom was torn), Heraclius (who questioned Abu Sufyan and acknowledged the truth but did not become Muslim), al-Mundhir, Hawdhah, al-Harith, and the two kings of ʿUman (who became Muslim). Only the text of the letter to Heraclius is established by hadith standards, but that does not deny that the letters were sent.",
    []),
], [
  q("q1", "seal", "لماذا اتخذ النبي ﷺ خاتمًا؟", "Why did the Prophet ﷺ take a seal ring?", [["لأن الملوك لا يقرؤون كتابًا إلا مختومًا", "Kings read no letter unless it is sealed"], ["للزينة", "For adornment"], ["لأن قريشًا طلبت ذلك", "Quraysh asked for it"]], 0, "ونقشه: محمد رسول الله.", "Engraved: Muhammad the Messenger of Allah."),
  q("q2", "authenticity", "أي الكتب يصح نصه حديثيًا عند العمري؟", "Which letter's text is sound by hadith standards per al-ʿUmari?", [["كتاب هرقل", "The letter to Heraclius"], ["كتاب كسرى", "The letter to Chosroes"], ["كتاب المقوقس", "The letter to al-Muqawqis"]], 0, "وهو في صحيح البخاري.", "It is in Sahih al-Bukhari."),
  q("q3", "kisra", "ماذا فعل كسرى بالكتاب؟", "What did Chosroes do with the letter?", [["مزقه", "He tore it up"], ["وضعه على عينه", "He placed it on his eye"], ["حفظه في حق من عاج", "He kept it in an ivory box"]], 0, "فدعا عليه النبي ﷺ أن يمزق ملكه.", "The Prophet ﷺ prayed that his kingdom be torn up."),
  q("q4", "muqawqis", "ماذا أهدى المقوقس؟", "What did al-Muqawqis send as a gift?", [["جاريتين، منهما مارية", "Two slave women, one of them Mariyah"], ["ذهبًا كثيرًا", "Much gold"], ["جيشًا", "An army"]], 0, "ومارية أم إبراهيم.", "Mariyah was the mother of Ibrahim."),
  q("q5", "abu-sufyan-2", "ماذا قال هرقل عن الإيمان إذا خالط القلوب؟", "What did Heraclius say of faith once it mixes with hearts?", [["لا يرتد عنه أحد سخطة لدينه", "No one leaves it out of displeasure with it"], ["يضعف مع الزمن", "It weakens over time"], ["يحتاج إلى سيف", "It needs a sword"]], 0, "وكذلك الإيمان حين تخالط بشاشته القلوب.", "So is faith when its delight mixes with the hearts."),
  q("q6", "abu-sufyan-1", "لماذا لم يكذب أبو سفيان على هرقل؟", "Why did Abu Sufyan not lie to Heraclius?", [["استحيا أن يُنقل عنه الكذب", "He was ashamed to have a lie reported from him"], ["لأنه كان مسلمًا", "He was already Muslim"], ["لأن هرقل هدده", "Heraclius threatened him"]], 0, "ولم يكن قد أسلم بعد.", "He had not yet become Muslim."),
  q("q7", "oman", "من حمل الكتاب إلى ملكي عمان؟", "Who carried the letter to the kings of ʿUman?", [["عمرو بن العاص", "ʿAmr ibn al-ʿAs"], ["دحية الكلبي", "Dihyah al-Kalbi"], ["حاطب بن أبي بلتعة", "Hatib ibn Abi Baltaʿah"]], 0, "فأسلما.", "Both became Muslim."),
]);
